'use strict';
// Four-pixel VFX texels: shaded sprite fragments, embers and broken ribbons.
const PIXEL=3;
const emojiCache=new Map();
function renderEmoji(type,x,y,size=43){let sprite=emojiCache.get(type);if(!sprite){if(typeof OffscreenCanvas==='undefined'&&!document.createElement)return;sprite=typeof OffscreenCanvas!=='undefined'?new OffscreenCanvas(96,96):document.createElement('canvas');sprite.width=sprite.height=96;const c=sprite.getContext('2d');c.font='72px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(EMOJIS[type],48,51);emojiCache.set(type,sprite);}ctx.drawImage(sprite,x-size/2,y-size/2,size,size);}
const INKS={'#ef9279':'#ff7854','#74cbc5':'#65e6c6','#b79ce4':'#b58bff','#e7bd6a':'#ffc469'};
const effectInk=color=>INKS[color]??color;
function texel(x,y,size,color,alpha=1){const opacity=ctx.globalAlpha;ctx.globalAlpha=opacity*alpha;ctx.fillStyle=color;ctx.fillRect(Math.round(x/PIXEL)*PIXEL,Math.round(y/PIXEL)*PIXEL,Math.max(PIXEL,Math.round(size/PIXEL)*PIXEL),Math.max(PIXEL,Math.round(size/PIXEL)*PIXEL));ctx.globalAlpha=opacity}
function tint(color,k){if(!/^#[0-9a-f]{6}$/i.test(color))return color;const n=parseInt(color.slice(1),16),c=[n>>16,(n>>8)&255,n&255].map(v=>Math.round(clamp(v*k,0,255)));return '#'+c.map(v=>v.toString(16).padStart(2,'0')).join('')}
const SPRITES={blast:['000011000001000','001122100112100','012332211233210','123443223444321','123444344444321','233444444443210','123444444444321','012344444443321','012344444443210','123344444432100','123443444332110','012332333232210','001221122122100','000110011011000','000000000000000'],spark:['00100','01210','12421','01210','00100'],ember:['0110','1241','1421','0110'],metal:['001','012','124','021','010'],mote:['010','121','242','121','010'],smoke:['0011100','0122210','1223221','1234321','1223221','0122210','0011100'],star:['0001000','0012100','0124210','1244421','0124210','0012100','0001000']};
const spriteCache=new Map();
function pixelSprite(x,y,color,size=1,style='spark',alpha=1){const cells=SPRITES[style]??SPRITES.spark,scale=Math.max(PIXEL,Math.round(size)*PIXEL),key=color+':'+style;let sprite=spriteCache.get(key);if(!sprite&&(typeof OffscreenCanvas!=='undefined'||document.createElement)){sprite=typeof OffscreenCanvas!=='undefined'?new OffscreenCanvas(cells[0].length,cells.length):document.createElement('canvas');sprite.width=cells[0].length;sprite.height=cells.length;const paint=sprite.getContext('2d'),palette=['',tint(color,.38),color,tint(color,1.25),style==='blast'?tint(color,1.45):'#fff8da'];for(let row=0;row<cells.length;row++)for(let col=0;col<cells[row].length;col++){const c=+cells[row][col];if(c){paint.fillStyle=palette[c];paint.fillRect(col,row,1,1)}}spriteCache.set(key,sprite)}const opacity=ctx.globalAlpha;ctx.globalAlpha=opacity*alpha;if(sprite){const smooth=ctx.imageSmoothingEnabled;ctx.imageSmoothingEnabled=false;ctx.drawImage(sprite,Math.round((x-cells[0].length*scale/2)/PIXEL)*PIXEL,Math.round((y-cells.length*scale/2)/PIXEL)*PIXEL,cells[0].length*scale,cells.length*scale);ctx.imageSmoothingEnabled=smooth}else{const palette=['',tint(color,.38),color,tint(color,1.25),style==='blast'?tint(color,1.45):'#fff8da'];for(let row=0;row<cells.length;row++)for(let col=0;col<cells[row].length;col++){const c=+cells[row][col];if(c){ctx.fillStyle=palette[c];ctx.fillRect(Math.round((x+(col-cells[0].length/2)*scale)/PIXEL)*PIXEL,Math.round((y+(row-cells.length/2)*scale)/PIXEL)*PIXEL,scale,scale)}}}ctx.globalAlpha=opacity}
function vfxNoise(i,seed=0){const n=Math.sin(i*127.1+seed*311.7)*43758.5453;return n-Math.floor(n)}
// Solid tapered slash silhouettes carry the attack. Small chips only mark contact.
function slashStroke(x,y,r,start,end,color,width=20,alpha=1){ctx.save();ctx.globalAlpha*=alpha;ctx.fillStyle=color;ctx.beginPath();const n=34;for(let i=0;i<=n;i++){const t=i/n,a=start+(end-start)*t,w=width*Math.sin(t*Math.PI*.88)*Math.sqrt(t),rr=r+w*.22;const px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}for(let i=n;i>=0;i--){const t=i/n,a=start+(end-start)*t,w=width*Math.sin(t*Math.PI*.88)*Math.sqrt(t);ctx.lineTo(x+Math.cos(a)*(r-w),y+Math.sin(a)*(r-w))}ctx.closePath();ctx.fill();ctx.restore()}
function pixelRibbon(x,y,r,start,end,color,width=12,alpha=1){slashStroke(x,y,r,start,end,color,width,alpha);slashStroke(x,y,r-1,start+(end-start)*.18,end,'#fff8e6',width*.3,alpha)}
function bladeStreak(x,y,angle,length,width,color,alpha=1){ctx.save();ctx.globalAlpha*=alpha;ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-length*.65,0);ctx.lineTo(length*.1,-width*.48);ctx.lineTo(length*.44,-width*.16);ctx.lineTo(length*.65,0);ctx.lineTo(length*.18,width*.45);ctx.closePath();ctx.fill();ctx.restore()}
function pixelBeam(x,y,tx,ty,color,width=12,alpha=1){const d=Math.hypot(tx-x,ty-y);bladeStreak((x+tx)/2,(y+ty)/2,Math.atan2(ty-y,tx-x),d,width,color,alpha)}
function hitGlyph(x,y,angle,r,color,progress,alpha=1){const size=r*(progress<.22?1:.8-progress*.5);bladeStreak(x,y,angle+.9,size*2.2,size*.35,color,alpha);bladeStreak(x,y,angle+.9,size*1.9,size*.13,'#fff',alpha);if(progress<.55){bladeStreak(x,y,angle-1.15,size*1.25,size*.21,'#fff4cb',alpha);bladeStreak(x,y,angle,size*.8,size*.15,'#fff',alpha)}}
function renderPixelParticle(p){const alpha=clamp(p.life/p.max,0,1);if(p.style==='shard'){const a=Math.atan2(p.vy,p.vx),length=clamp(Math.hypot(p.vx,p.vy)*.085,12,48);bladeStreak(p.x,p.y,a,length,p.size*1.15,p.color,alpha);bladeStreak(p.x,p.y,a,length*.65,2,'#f7ffe9',alpha);texel(p.x,p.y,3,'#eaffdd',alpha*.8);return;}if(p.style==='mote'){texel(p.x,p.y,3,p.color,alpha*.65);return}const a=Math.atan2(p.vy,p.vx),length=clamp(Math.hypot(p.vx,p.vy)*.07,10,38);if(p.style==='debris'){pixelSprite(p.x,p.y,p.color,p.size/3,'ember',alpha*.8);bladeStreak(p.x,p.y,a,length,4,p.color,alpha*.55);return}bladeStreak(p.x,p.y,a,length,p.size*1.5,p.color,alpha);bladeStreak(p.x,p.y,a,length*.55,2.5,'#fff6dc',alpha);if(p.max-p.life<.1)pixelSprite(p.x,p.y,p.color,1,'metal',alpha*.7);}
function clashBurst(x,y,color,power,angle=0){const force=clamp(power/45,1,1.7);fx('clash',x,y,'#fff0b8',.36,{r:130+Math.min(60,power*.7),angle});for(let i=0;i<40;i++){const a=angle+(i%2?Math.PI:0)+visualRandom(-.65,.65),speed=visualRandom(430,870)*force,life=visualRandom(.18,.34);particles.push({x,y,px:x,py:y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,color:i%3?'#ffd28c':'#fff7d5',life,max:life,size:visualRandom(4,7),style:'shard'});}if(particles.length>PARTICLE_BUDGET)particles.splice(0,particles.length-PARTICLE_BUDGET);impactPause(3.4,angle)}
function renderClashImpact(x,y,a,r,p,alpha){const flash=Math.pow(1-p,1.8),expand=1-Math.pow(1-p,3);hitGlyph(x,y,a,r*.9,'#ffc66b',p,flash);if(p<.48)hitGlyph(x,y,a,r*.62,'#fff8e0',p,flash);const radius=r*(.18+.82*expand),width=Math.max(2,15*(1-p));for(const side of [0,Math.PI]){slashStroke(x,y,radius,a+side-.7,a+side+.7,'#ffca79',width,alpha*.85);slashStroke(x,y,radius+3,a+side-.55,a+side+.55,'#fff7d7',width*.3,alpha);}for(let i=0;i<8;i++){const angle=a+i*Math.PI/4,d=radius*(i%2?1:.78);bladeStreak(x+Math.cos(angle)*d,y+Math.sin(angle)*d,angle,28*(1-p),5*(1-p),'#ffe4aa',alpha*.65);}}
function renderDeathWave(e){const p=1-e.life/e.max,alpha=Math.pow(1-p,1.5),expand=1-Math.pow(1-p,3),r=e.r*(.08+.92*expand);ctx.save();ctx.globalAlpha*=alpha;circle(e.x,e.y,r,e.color,false,Math.max(3,16*(1-p)));circle(e.x,e.y,r+3,'#f3ffe5',false,Math.max(2,5*(1-p)));if(p>.12){const q=clamp((p-.12)/.88,0,1);circle(e.x,e.y,e.r*.8*(1-Math.pow(1-q,3)),e.color,false,Math.max(2,8*(1-q)));}for(let i=0;i<12;i++){const a=i*Math.PI/6+e.angle,d=r+10;bladeStreak(e.x+Math.cos(a)*d,e.y+Math.sin(a)*d,a,22*(1-p),4,e.color,alpha*.65);}ctx.restore();}
function renderCombatWave(w){const p=clamp(w.t/w.duration,0,1),alpha=clamp(w.life/.35,0,1),parry=w.kind==='parry';for(let i=0;i<10;i++){const angle=i*2.39996+vfxNoise(i,w.x)*.45,radius=Math.max(12,w.r*p*(.5+vfxNoise(i,w.y)*.5));bladeStreak(w.x+Math.cos(angle)*radius,w.y+Math.sin(angle)*radius,angle,24*(1-p*.5),parry?5:4,w.color,alpha*.75);}if(p<.5)hitGlyph(w.x,w.y,Math.PI/4,parry?90:65,w.color,p*2,alpha*.85);}

function renderItemEffect(e){
 const p=clamp(1-e.life/e.max,0,1),alpha=Math.pow(1-p,1.1),u=e.unitId?units.find(v=>v.id===e.unitId&&v.hp>0):null,x=u?.x??e.x,y=u?.y??e.y;
 if(e.unitId&&!u)return;
 if(e.kind==='totemPulse'){
  const radius=e.r*(.1+.9*(1-Math.pow(1-p,2))),charge=e.itemKind==='charge';
  ctx.save();ctx.globalAlpha*=alpha*.09;circle(x,y,radius,e.color);ctx.restore();
  ctx.save();ctx.globalAlpha*=alpha;circle(x,y,radius,e.color,false,Math.max(2,7*(1-p)));circle(x,y,radius-3,charge?'#fff6b8':'#d4ffe1',false,2);ctx.restore();
  for(let i=0;i<18;i++){const a=i*2.39996,d=radius*(.65+vfxNoise(i,e.x)*.4);pixelSprite(x+Math.cos(a)*d,y+Math.sin(a)*d, e.color,1,charge?'star':'mote',alpha*.85);}
  return;
 }
 const growth=e.kind==='itemGrowth',necklace=e.kind==='necklaceHeal',r=(e.r??42)*(.75+.25*p);
 for(let i=0;i<(growth?7:5);i++){const a=i*2.39996,d=r*(.7+vfxNoise(i,e.x)*.2),rise=p*(growth?55:30);pixelSprite(x+Math.cos(a)*d,y+Math.sin(a)*d-rise,e.color,1,e.itemKind==='charge'?'star':growth?'metal':'mote',alpha);}
 ctx.save();ctx.globalAlpha*=alpha*.8;slashStroke(x,y,r,-2.6,-.4,e.color,necklace?7:10);slashStroke(x,y,r,.55,2.7,e.color,necklace?7:10);ctx.restore();
}
function renderEffect(e){if(e.kind==='awlPin'){renderAwlPin(e);return;}if(['totemPulse','totemReceipt','necklaceHeal','itemGrowth'].includes(e.kind)){renderItemEffect(e);return;}if(['puppetTransfer','puppetSnap','puppetBind'].includes(e.kind)){renderPuppetEffect(e);return;}if(e.kind==='mirrorFlash'){renderMirrorFlash(e);return;}if(['lightningLink','lightningDischarge','shockBurst','faithPrayer','faithRage'].includes(e.kind)){renderFaithLightningEffect(e);return;}if(['heroArrival','tankBlast','tankLoad'].includes(e.kind)){renderHeroTankEffect(e);return;}if(e.kind==='bombBlast'){renderBombBlast(e);return;}if(['bite','devour','scales'].includes(e.kind)){const p=1-e.life/e.max;renderPredatorEffect(e,p,1-p);return;}const progress=1-e.life/e.max,alpha=1-progress,u=e.unitId?units.find(u=>u.id===e.unitId):null,x=u?.x??e.x,y=u?.y??e.y,r=e.r??50,a=e.angle??0;
if(e.kind==='curseMark'||e.kind==='curseField'){renderCurseEffect(e,progress,alpha);return;}if(e.kind==='text'){if(!/^[−-]\d+$/.test(String(e.text)))return;ctx.save();ctx.globalAlpha*=Math.min(1,e.life/.2);ctx.font=`900 ${e.color==='#ffdd88'?29:23}px monospace`;ctx.textAlign='center';ctx.lineWidth=4;ctx.strokeStyle='#08110ff0';const rise=(1-Math.pow(1-progress,3))*28;ctx.strokeText(e.text,e.x,e.y-rise);ctx.fillStyle=e.color;ctx.fillText(e.text,e.x,e.y-rise);ctx.restore();return}
if(e.kind==='sweep'||e.kind==='doubleSlash'||e.kind==='bash'||e.kind==='ring')return;
if(e.kind==='clash'){renderClashImpact(x,y,a,r,progress,alpha);return}
if(e.kind==='impact'||e.kind==='metalHit'){hitGlyph(x,y,a,r,e.kind==='impact'?effectInk(e.color):'#ffcf70',progress,alpha);return}
if(e.kind==='issenCut'){renderIssenCut({x:e.x,y:e.y},{x:e.tx,y:e.ty},e.width,alpha);return;}
if(e.kind==='paladinBlessing'){for(const side of [-1,1])bladeStreak(x+side*28,y-10-progress*55,-Math.PI/2,45*(1-progress),9,'#fff0b8',alpha);hitGlyph(x,y-38,-Math.PI/2,24,'#fff4d2',progress,alpha);return;}
if(e.kind==='machineTrail'){pixelBeam(e.x,e.y,e.tx,e.ty,'#d6ba71',4,alpha*.6);pixelBeam(e.x,e.y,e.tx,e.ty,'#fff1c4',1.5,alpha*.9);return;}
if(e.kind==='sniperTrail'){pixelBeam(e.x,e.y,e.tx,e.ty,'#ffd293',8,alpha*.8);pixelBeam(e.x,e.y,e.tx,e.ty,'#fff4cf',3,alpha);return;}
if(e.kind==='gunFlash'){hitGlyph(x,y,a,r,'#ffce83',progress,alpha);bladeStreak(x,y,a,r*1.4,18,'#fff4cd',alpha);return;}
if(e.kind==='repel'){slashStroke(x,y,r*.7,a-1.2,a+1.2,'#ffe0a6',22,alpha);hitGlyph(x+Math.cos(a)*50,y+Math.sin(a)*50,a,65,'#fff0c4',progress,alpha);return;}
if(e.kind==='muzzle'){bladeStreak(x,y,a,50,20,e.color,alpha);bladeStreak(x,y,a,31,8,'#fff',alpha);return}
if(e.kind==='explosion'){ctx.save();ctx.globalAlpha*=alpha;const size=r*(.25+Math.sin(Math.min(progress*2,1)*Math.PI/2)*.5);ctx.fillStyle=progress<.28?'#fff4ff':e.color;ctx.beginPath();for(let i=0;i<24;i++){const aa=i*Math.PI/12,rr=size*(i%2?.48:1)*(1+(i%3)*.09);i?ctx.lineTo(x+Math.cos(aa)*rr,y+Math.sin(aa)*rr):ctx.moveTo(x+rr,y)}ctx.closePath();ctx.fill();ctx.globalAlpha*=.6;slashStroke(x,y,size*1.18,-2.7,-.2,'#dfc0ff',9);slashStroke(x,y,size*1.18,.35,2.5,'#dfc0ff',9);ctx.restore();return}
if(e.kind==='lightBurst'){hitGlyph(x,y,a,Math.min(25,r),'#9ee8ff',progress,alpha*.8);return}
if(e.kind==='parrySuccess'){const size=r*(.65+.35*Math.sin(progress*Math.PI));slashStroke(x,y,size,a-1.5,a+1.5,'#77dbf1',24,alpha);slashStroke(x,y,size+4,a-1.25,a+1.3,'#f4ffff',8,alpha);hitGlyph(x+Math.cos(a)*36,y+Math.sin(a)*36,a,r*.7,'#ddfaff',progress,alpha);return;}
if(e.kind==='parryPulse'){const radius=r*(.2+.8*progress);slashStroke(x,y,radius,-2.8,-.2,'#a6e6f3',8,alpha*.75);slashStroke(x,y,radius,.25,2.7,'#edfdff',4,alpha);for(let i=0;i<12;i++){const aa=i*Math.PI/6;bladeStreak(x+Math.cos(aa)*radius,y+Math.sin(aa)*radius,aa,20,4,'#d5faff',alpha);}return;}
if(e.kind==='barrierGain'||e.kind==='barrierHit'){hitGlyph(x,y,a,r*.6,e.color,progress,alpha*.6);for(let i=0;i<5;i++){const angle=i*2.4;bladeStreak(x+Math.cos(angle)*r*progress,y+Math.sin(angle)*r*progress,angle,18,4,e.color,alpha);}return;}
if(e.kind==='parryBreak'){hitGlyph(x,y,a,r*.7,'#e9b77f',progress,alpha);return;}
if(e.kind==='basicParry'){if(!u||!basicParryPerfect(u))return;const face=u.face;slashStroke(x,y,52*unitScale(u),face-1.3,face+1.3,'#75d7eb',14,alpha*.7);slashStroke(x,y,54*unitScale(u),face-1.15,face+1.15,'#edfdff',4,alpha);return;}
if(e.kind==='parry'||e.kind==='shield'){slashStroke(x,y,r*.7,a-1.15,a+1.15,'#ffc86b',16,alpha);slashStroke(x,y,r*.7,a-.8,a+.95,'#fff6d9',5,alpha);return}
if(e.kind==='afterimage'){if(e.ownerId&&units.find(u=>u.id===e.ownerId)?.hp<=0)return;ctx.save();ctx.globalAlpha*=alpha*.2;renderEmoji(e.type,e.x,e.y,43);ctx.restore();bladeStreak((e.x+e.tx)/2,(e.y+e.ty)/2,Math.atan2(e.ty-e.y,e.tx-e.x),Math.min(100,Math.hypot(e.tx-e.x,e.ty-e.y)),7,e.color,alpha*.3);return}
if(e.kind==='charge'){if(!u)return;const p=u.attack?.phase==='windup'?u.attack.t/u.attack.profile.windup:0,face=u.attack?.angle??u.face,cx=u.x+Math.cos(face)*33,cy=u.y+Math.sin(face)*33;if(p>.72){hitGlyph(cx,cy,face,9+p*8,u.color,0,.6+p*.3)}return}
if(e.kind==='healBeam'){pixelBeam(e.x,e.y,e.tx,e.ty,e.color,3,alpha*.45);return}
if(e.kind==='heal'){for(let i=0;i<3;i++){const xx=x+(i-1)*16,yy=y-8-progress*30+i%2*9;bladeStreak(xx,yy,-Math.PI/2,8,5,'#9aeebc',alpha*.7)}return}
if(e.kind==='portal'){bladeStreak(x,y,-Math.PI/2,r*.85,14,e.color,alpha);bladeStreak(x,y,-Math.PI/2,r*.65,5,'#fff2ff',alpha);return}
if(e.kind==='smoke'){ctx.save();ctx.globalAlpha*=alpha*.23;ctx.fillStyle='#263a35';for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(x+(i-1)*13,y+6,18+progress*10,11,0,0,Math.PI*2);ctx.fill()}ctx.restore();return}
if(e.kind==='deathWave'){renderDeathWave(e);return}
if(e.kind==='stun')renderStunPixels({x,y})}
function renderProjectileShape(p){if(p.kind==='openingAwl'){renderOpeningAwl(p);return;}if(p.kind==='sharpThread'||p.kind==='controlThread'){renderPuppetThread(p);return;}if(p.kind==='frogTongue'){renderFrogTongue(p);return;}if(p.kind==='frogBody'){renderFrogBody(p);return;}if(p.kind==='machineBullet'){const angle=Math.atan2(p.vy,p.vx);bladeStreak(p.x,p.y,angle,125,5,'#e7cc84',.9);bladeStreak(p.x,p.y,angle,65,2,'#fff9dd');return;}if(p.kind==='star'){renderGalaxyStar(p);return;}if(p.kind==='mirrorLight'||p.kind==='mirrorReflection'){renderMirrorProjectile(p);return;}if(p.kind==='lightning'){renderChainLightning(p);return;}if(p.kind==='tankShell'){renderTankShell(p);return;}if(p.kind==='missile'){renderSatelliteMissile(p);return;}if(p.kind==='bomb'){renderBombProjectile(p);return;}if(p.kind==='sniper'){const a=Math.atan2(p.vy,p.vx);bladeStreak(p.x,p.y,a,170,9,'#ffcc8e',.9);bladeStreak(p.x,p.y,a,90,3,'#fff6d9');return;}if(p.kind==='pellet'){const a=Math.atan2(p.vy,p.vx);bladeStreak(p.x,p.y,a,22,6,'#ffd298');pixelSprite(p.x,p.y,'#fff0cb',1,'ember',.8);return;}if(p.ultimate){renderUltimateProjectile(p);return}const a=Math.atan2(p.vy,p.vx);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);if(p.type===1){bladeStreak(-17,0,0,54,3,'#e4eec2',.9);ctx.fillStyle='#fff4d0';ctx.beginPath();ctx.moveTo(13,0);ctx.lineTo(3,-4);ctx.lineTo(3,4);ctx.closePath();ctx.fill();ctx.fillStyle='#b1c989';ctx.fillRect(-25,-4,6,2);ctx.fillRect(-25,2,6,2)}else{bladeStreak(-12,0,0,p.type===2?56:34,p.type===2?18:10,p.color,.7);bladeStreak(0,0,0,p.type===2?27:18,p.type===2?15:8,'#f7ecff');}ctx.restore();}
function renderMeleeStrikes(){for(const s of meleeStrikes){if(!strikeLive(s))continue;if(s.grappleTarget!=null)continue;if(s.dashSlash){renderIssenCut(s.dashOrigin??s.source,s.dashEnd??s.source,s.pathWidth,.9);continue;}if(s.shieldBash){const b=strikeBlade(s),x=(b.a.x+b.b.x)/2,y=(b.a.y+b.b.y)/2;slashStroke(x-Math.cos(s.angle)*35,y-Math.sin(s.angle)*35,70*s.visualScale,s.angle-.9,s.angle+.9,'#f3dd9e',32,.85);slashStroke(x-Math.cos(s.angle)*35,y-Math.sin(s.angle)*35,72*s.visualScale,s.angle-.75,s.angle+.75,'#fff6d7',10,.95);continue;}if(s.swordCombo&&s.finisher){renderSwordFinisher(s);continue;}if(s.bite){renderBiteStrike(s);continue;}if(s.headbutt){const b=strikeBlade(s);bladeStreak(b.b.x,b.b.y,b.angle,80*(s.visualScale??1),26*(s.visualScale??1),'#c2faff',.75);continue;}if(s.heroPunch){renderHeroStrike(s);continue;}if(s.punch){const b=strikeBlade(s);bladeStreak((b.a.x+b.b.x)/2,(b.a.y+b.b.y)/2,b.angle,(s.finisher?100:65)*(s.visualScale??1),(s.finisher?24:15)*(s.visualScale??1),s.finisher?'#ffe4bc':s.color,.85);bladeStreak(b.b.x,b.b.y,b.angle,35,8,'#fff4de');continue;}const b=strikeBlade(s),r=s.reach*.88,width=(s.visualScale??1)*(s.ultimate?54:s.swordCombo&&s.finisher?58:s.source.type===3?24:s.source.type===4?36:s.source.type===10?66:36);slashStroke(s.source.x,s.source.y,r,b.angle-1.18,b.angle,effectInk(s.color),width,.92);slashStroke(s.source.x,s.source.y,r-1,b.angle-.72,b.angle,'#fff8ec',width*.38,1);if(s.source.type===3)slashStroke(s.source.x,s.source.y,r*.65,b.angle-1.4,b.angle-.28,'#b2ffdf',10,.8);if(s.ultimate)slashStroke(s.source.x,s.source.y,r*.72,b.angle-1.45,b.angle-.12,'#ffaf78',18,.7)}}
function renderGuardianAura(u){for(const v of alive())if(v.id!==u.id&&v.faction===u.faction&&dist(u,v)<=165*unitScale(u)){ctx.save();ctx.globalAlpha*=.5;ctx.strokeStyle='#d7bd74';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(v.x-21,v.y+28);ctx.lineTo(v.x-12,v.y+32);ctx.lineTo(v.x+12,v.y+32);ctx.lineTo(v.x+21,v.y+28);ctx.stroke();ctx.restore()}}
function renderTacticalStatus(u){if(activeShieldHp(u)>0){ctx.save();ctx.globalAlpha=.5;ctx.fillStyle='#86cbdc18';ctx.strokeStyle='#a5e3ef';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<6;i++){const a=i*Math.PI/3+Math.PI/6,x=u.x+Math.cos(a)*36,y=u.y+Math.sin(a)*36;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.fill();ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#143440';ctx.fillRect(u.x-28,u.y-36,56,3);ctx.fillStyle='#a5e3ef';ctx.fillRect(u.x-28,u.y-36,56*clamp(u.shieldHp/100,0,1),3);ctx.restore();}if(u.ironDefenseTime>0)for(let i=0;i<3;i++)bladeStreak(u.x-10+i*10,u.y-67,Math.PI/2,8,4,'#dce9b2',.75);}
function renderStunPixels(u){for(let i=0;i<3;i++){const a=elapsed*3+i*Math.PI*2/3;bladeStreak(u.x+Math.cos(a)*18,u.y-30+Math.sin(a)*4,Math.PI/4,7,4,'#d5b7ee',.8)}}
function renderUltimateZones(){for(const z of ultimateZones){const alpha=Math.min(1,z.life)*ctx.globalAlpha,t=z.pulse;ctx.save();if(z.kind==='galaxy'){renderGalaxyZone(z,alpha);ctx.restore();continue;}if(z.kind==='tankFire'){renderTankFire(z,alpha);ctx.restore();continue;}if(z.kind==='ring'){renderRingZone(z);ctx.restore();continue;}if(z.kind==='holy'){renderHolyGround(z,alpha);ctx.restore();continue;}if(z.kind==='healing'){ctx.globalAlpha=alpha*.07;ctx.fillStyle='#56c38d';ctx.beginPath();ctx.arc(z.x,z.y,z.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=alpha*.3;ctx.strokeStyle='#8de4ae';ctx.lineWidth=2;ctx.beginPath();ctx.arc(z.x,z.y,z.r,0,Math.PI*2);ctx.stroke();for(let i=0;i<7;i++){const a=i*2.4,r=z.r*.7*vfxNoise(i,z.x),rise=(t*15+i*11)%60;bladeStreak(z.x+Math.cos(a)*r,z.y+Math.sin(a)*r-rise*.3,-1.15,9,4,'#b7f8c9',alpha*(1-rise/70)*.45)}}else{ctx.globalAlpha=alpha*.3;ctx.fillStyle='#271e43';ctx.beginPath();ctx.ellipse(z.x,z.y,z.r*.75,z.r*.48,0,0,Math.PI*2);ctx.fill();for(let i=0;i<3;i++){const start=t*1.8+i*Math.PI*2/3;slashStroke(z.x,z.y,40+i*25,start,start+3.7,i===2?'#74549f':'#b59add',9,alpha*.75)}ctx.globalAlpha=alpha;ctx.fillStyle='#080b15';ctx.beginPath();ctx.ellipse(z.x,z.y,25,18,0,0,Math.PI*2);ctx.fill();slashStroke(z.x,z.y,28,t*2,t*2+4.5,'#ddd0f4',4,alpha*.9)}ctx.restore()}}
function renderUltimateUnitShape(u){if(u.type===21&&u.mirrorReflectTime>0)renderMirrorGuard(u);if((u.parryTime??0)>0){const face=u.face,perfect=basicParryPerfect(u);slashStroke(u.x,u.y,43*unitScale(u),face-1.3,face+1.3,perfect?'#d0fbff':'#76bed1',perfect?8:4,perfect?.85:.55);}if(u.invincible>0){slashStroke(u.x,u.y,39,-2.6,-.45,'#ead292',6,.65);slashStroke(u.x,u.y,39,.45,2.6,'#ead292',6,.65)}if(u.shadowTime>0){bladeStreak(u.x-u.vx*.12,u.y-u.vy*.12,u.face,45,16,'#508b83',.15)}texel(u.x+Math.cos(u.face)*35,u.y+Math.sin(u.face)*35,3,'#e0e9ce',.7);if(!u.ultCast)return;if(u.type===11&&u.ultCast.multiStarted)return;const a=u.ultCast,p=clamp(a.t/a.duration,0,1),cx=u.x+Math.cos(a.angle)*35,cy=u.y+Math.sin(a.angle)*35;
if(u.type===17&&a.dashing){bladeStreak(u.x-Math.cos(a.angle)*48,u.y-Math.sin(a.angle)*48,a.angle,110,18,'#ffaab0',.65);return;}if(u.type===14&&a.dashing){bladeStreak(u.x-Math.cos(a.angle)*55,u.y-Math.sin(a.angle)*55,a.angle,140,12,'#b9e9f5',.5);return;}if(u.type===1){ctx.save();ctx.translate(u.x,u.y);ctx.rotate(a.angle);ctx.strokeStyle='#c1d283';ctx.lineWidth=4;ctx.beginPath();ctx.arc(28,0,48,-1.4,1.4);ctx.stroke();ctx.strokeStyle='#fff3cc';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(36,-47);ctx.lineTo(-24-p*34,0);ctx.lineTo(36,47);ctx.stroke();ctx.restore();bladeStreak(cx,cy,a.angle,80+p*30,5+p*4,'#e5f4ac');for(let i=0;i<5;i++){const d=120+i*120;bladeStreak(u.x+Math.cos(a.angle)*d,u.y+Math.sin(a.angle)*d,a.angle,17,2,'#bfd582',.18)}if(p>.8)hitGlyph(cx,cy,a.angle,12+p*12,'#ebffc8',0,.9)}else if(u.type===0||u.type===3){const face=a.angle-1.5-p*.7;bladeStreak(u.x+Math.cos(face)*65,u.y+Math.sin(face)*65,face,75,10,'#fff3d4');}else{hitGlyph(cx,cy,a.angle,8+p*17,u.color,0,.4+p*.5)}}
function renderUltimateProjectile(p){const a=Math.atan2(p.vy,p.vx);if(p.ultimate==='greatImpact'){renderGreatImpact(p);return;}if(p.ultimate==='giantArrow'){bladeStreak(p.x-20*Math.cos(a),p.y-20*Math.sin(a),a,288,29,'#c7e78c',.45);bladeStreak(p.x,p.y,a,216,13,'#fff3c6');ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);ctx.scale(1.6,1.6);ctx.fillStyle='#e4efac';ctx.beginPath();ctx.moveTo(52,0);ctx.lineTo(16,-19);ctx.lineTo(24,0);ctx.lineTo(16,19);ctx.closePath();ctx.fill();ctx.restore()}else{slashStroke(p.x,p.y,60,a-1.4,a+1.4,'#ffb78a',32);slashStroke(p.x,p.y,59,a-1.15,a+1.25,'#fff5da',12);slashStroke(p.x-20*Math.cos(a),p.y-20*Math.sin(a),58,a-1.5,a+1.5,'#dc8261',10,.35)}}

function renderProjectile(p){ctx.save();scaleAround(p,p.visualScale??1);renderProjectileShape(p);ctx.restore();}
function renderUltimateUnit(u){ctx.save();scaleAround(u,unitScale(u));renderBattleEffects(()=>renderUltimateUnitShape(u));ctx.fillStyle='#111923';ctx.fillRect(u.x-28,u.y-(u.type===6?63:54),56,3);ctx.fillStyle=u.ultGauge>=100?'#efd9ff':'#a27bce';ctx.fillRect(u.x-28,u.y-(u.type===6?63:54),56*u.ultGauge/100,3);ctx.restore();}

function renderIssenCut(from,to,width,alpha=1){
 const length=dist(from,to);if(length<1)return;const angle=Math.atan2(to.y-from.y,to.x-from.x);ctx.save();ctx.translate(from.x,from.y);ctx.rotate(angle);const opacityBase=ctx.globalAlpha*alpha;
 for(const [color,w,opacity]of[['#558aa5',width*.82,.35],['#b4eaff',width*.55,.8],['#f2ffff',width*.18,1]]){ctx.globalAlpha=opacityBase*opacity;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-12,0);ctx.lineTo(length*.22,-w*.6);ctx.lineTo(length*.82,-w*.4);ctx.lineTo(length+24,0);ctx.lineTo(length*.58,w*.35);ctx.lineTo(length*.08,w*.22);ctx.closePath();ctx.fill();}
 ctx.globalAlpha=opacityBase;for(let i=1;i<=Math.min(8,Math.floor(length/40));i++)texel(length*i/(Math.min(8,Math.floor(length/40))+1),i%2?width*.4:-width*.42,3,'#dcfbff',alpha*.7);ctx.restore();
}

function renderHolyGround(z,alpha){
 const grow=Math.min(1,(z.max-z.life)/.35),r=z.r*(.8+.2*grow),pulse=.9+.1*Math.sin(z.pulse*2.5);ctx.save();
 const light=ctx.createRadialGradient(z.x,z.y,0,z.x,z.y,r);light.addColorStop(0,'#ffe8a6');light.addColorStop(.65,'#e8c34e');light.addColorStop(1,'#a98626');ctx.globalAlpha=alpha*.18*pulse;ctx.fillStyle=light;ctx.beginPath();ctx.arc(z.x,z.y,r,0,Math.PI*2);ctx.fill();
 ctx.globalAlpha=alpha*.55;circle(z.x,z.y,r,'#f9db83',false,2);ctx.globalAlpha=alpha*.28;circle(z.x,z.y,r*.88,'#ffeaa3',false,1);
 for(let i=0;i<12;i++){const a=i*Math.PI/6+z.pulse*.035,x=z.x+Math.cos(a)*r*.93,y=z.y+Math.sin(a)*r*.93;bladeStreak(x,y,a,15,5,'#ffeab0',alpha*.65);bladeStreak(x,y,a+Math.PI/2,10,3,'#fff4d1',alpha*.75);}
 ctx.globalAlpha=alpha;for(let i=0;i<9;i++){const a=i*2.39996,d=r*(.22+.58*vfxNoise(i,z.x)),rise=(z.pulse*20+i*13)%65;texel(z.x+Math.cos(a)*d,z.y+Math.sin(a)*d-rise*.45,3,'#fff3ba',alpha*(1-rise/70)*.55);}
 ctx.restore();
}
function renderSwordFinisher(s){
 const phase=clamp(s.age/s.duration,0,1),a=s.angle-Math.PI+phase*Math.PI*2,r=s.reach*.96;
 slashStroke(s.source.x,s.source.y,r,a-4.1,a,'#70b6d0',64*s.visualScale,.75);slashStroke(s.source.x,s.source.y,r+3,a-3.3,a,'#defaff',24*s.visualScale,.95);
 slashStroke(s.source.x,s.source.y,r*.87,a+Math.PI-1.7,a+Math.PI,'#b0e4f4',24*s.visualScale,.55);
 bladeStreak(s.source.x+Math.cos(a)*r,s.source.y+Math.sin(a)*r,a+Math.PI/2,90*s.visualScale,14*s.visualScale,'#f7ffff',.95);
 for(let i=0;i<5;i++){const angle=a-i*.72;texel(s.source.x+Math.cos(angle)*(r+9),s.source.y+Math.sin(angle)*(r+9),3,'#d2f8ff',.6-i*.08);}
}
